// ─────────────────────────────────────────────────────────────
// STEP 1: Build the AI prompt
// Desert Cubs target keywords — update this list whenever
// you want to shift SEO focus.
// ─────────────────────────────────────────────────────────────

const today = new Date();
const dateStr = today.toISOString().slice(0, 10);

const targetKeywords = [
  'UAE Junior Cricket Coaching',
  'Sharjah Junior Cricket Coaching',
  'UAE Summer Camp Cricket',
  'Best Cricket Academy in UAE',
  'Best Cricket Academy in Dubai',
  'UAE National Cricket Player Pathway',
  'Best Cricket Ground in UAE',
  'Advanced Player Analysis Junior Cricket UAE',
  'Junior International Cricket Tournament UAE',
  'Junior International Cricket Tour UAE',
  'Most Cricket Tournaments in UAE'
];

// Pick a different keyword focus each week (cycles through the list)
const weekNumber = Math.floor(Date.now() / (7 * 24 * 60 * 60 * 1000));
const focusKeyword = targetKeywords[weekNumber % targetKeywords.length];

const systemPrompt = `You are an expert SEO content writer for Desert Cubs Cricket Academy — UAE's best junior cricket academy at www.desertcubs.com. The academy was founded in 2007, has 15,000+ alumni, and 6 training centres across Dubai and Sharjah with ICC-certified coaches for ages 4–19. Write content that is genuinely helpful to UAE parents and junior cricketers.`;

const userPrompt = `Today's date: ${dateStr}\nThis week's focus keyword: "${focusKeyword}"\n\nWrite a brand new blog post for Desert Cubs Cricket Academy targeting the focus keyword above. The blog must:\n- Be at least 500 words\n- Use the focus keyword and related terms naturally throughout\n- Include practical tips or information that parents/players in UAE will find useful\n- Mention Desert Cubs Academy naturally (not as spam)\n- End with a clear call-to-action to enrol or contact Desert Cubs\n\nReturn ONLY a valid JSON object with these exact keys (no markdown, no code block, pure JSON):\n{\n  \

\n}`;

const openaiRequest = {
  model: 'gpt-4o',
  response_format: { type: 'json_object' },
  temperature: 0.8,
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user',   content: userPrompt }
  ]
};

return [{ json: { openaiRequest, focusKeyword, dateStr } }];

// ─────────────────────────────────────────────────────────────
// STEP 2: Parse AI response & prepare GitHub file payloads
// ─────────────────────────────────────────────────────────────

const aiResponse = $input.first().json;
const buildStep  = $('Build AI Prompt').first().json;

// Parse the JSON returned by OpenAI
let parsed;
try {
  parsed = JSON.parse(aiResponse.choices[0].message.content);
} catch(e) {
  throw new Error('OpenAI did not return valid JSON. Response: ' +
    aiResponse.choices[0].message.content.slice(0, 300));
}

// ── Validate required fields ──
const required = ['seo_keywords', 'seo_title', 'seo_description', 'blog_title', 'blog_html'];
for (const field of required) {
  if (!parsed[field]) throw new Error(`AI response missing field: ${field}`);
}

// ── Build filename: YYYY-MM-DD_slug-title.html ──
const slug = parsed.blog_title
  .toLowerCase()
  .replace(/[^a-z0-9\s-]/g, '')
  .trim()
  .replace(/\s+/g, '-')
  .replace(/-+/g, '-')
  .slice(0, 60)
  .replace(/-$/g, '');
const filename = `${buildStep.dateStr}_${slug}.html`;

// ── Build updated seo.json content ──
const seoData = JSON.stringify({
  title:       parsed.seo_title,
  description: parsed.seo_description,
  keywords:    Array.isArray(parsed.seo_keywords)
               ? parsed.seo_keywords.join(', ')
               : parsed.seo_keywords
}, null, 2);

// ── Base64 encode for GitHub API ──
const blogBase64 = Buffer.from(parsed.blog_html, 'utf-8').toString('base64');
const seoBase64  = Buffer.from(seoData, 'utf-8').toString('base64');

return [{
  json: {
    filename,
    blogBase64,
    seoBase64,
    blogTitle:     parsed.blog_title,
    focusKeyword:  buildStep.focusKeyword,
    dateStr:       buildStep.dateStr,
    commitBlog:    `auto(n8n): new blog – ${parsed.blog_title}`,
    commitSeo:     `auto(n8n): update SEO keywords ${buildStep.dateStr} – ${buildStep.focusKeyword}`
  }
}];
